  ('roasted-ground-blend-70-30', 'Roasted & Ground Coffee 70/30', 'coffee', '70% Robusta · 30% Arabica', 'A roasted and ground blend of 70% Vietnamese Robusta and 30% Arabica, packed in valve bags for retail, HoReCa and private label.', 'A ready-to-sell blend: Robusta from the Central Highlands gives body and crema, Arabica from Lam Dong adds aroma. Roasted to the profile you agree with us, ground for espresso, filter or phin, and packed in one-way-valve bags — under your own label on request.', '/photos/roasted-beans-bags.jpg', array['/photos/roasting-packing-line.jpg']::text[], 'Robusta: Central Highlands · Arabica: Lam Dong', '[{"label":"Blend","value":"70% Robusta / 30% Arabica"},{"label":"Form","value":"Roasted & ground (whole bean on request)"},{"label":"Roast level","value":"Agreed per order"},{"label":"Grind","value":"Espresso, filter or phin — to order"}]'::jsonb, 'Bags with one-way degassing valve; private label on request', 'On request', false, 70, '{"ru":{"name":"Молотый жареный кофе 70/30","grade":"70% робуста · 30% арабика","summary":"Жареный молотый бленд из 70% вьетнамской робусты и 30% арабики в пакетах с клапаном — для розницы, HoReCa и частной марки.","description":"Готовый к продаже бленд: робуста из Центрального нагорья даёт плотность и крему, арабика из Ламдонга — аромат. Обжариваем по согласованному с вами профилю, мелем для эспрессо, фильтра или фина и фасуем в пакеты с односторонним клапаном — по запросу под вашей маркой.","origin":"Робуста: Центральное нагорье · Арабика: Ламдонг","specs":[{"label":"Бленд","value":"70% робуста / 30% арабика"},{"label":"Форма","value":"Жареный молотый (зерно — по запросу)"},{"label":"Степень обжарки","value":"Согласуется в заказе"},{"label":"Помол","value":"Эспрессо, фильтр или фин — под заказ"}],"packaging":"Пакеты с односторонним клапаном дегазации; частная марка по запросу","moq":"По запросу"},"ar":{"name":"قهوة محمّصة ومطحونة 70/30","grade":"70% روبوستا · 30% أرابيكا","summary":"خلطة محمّصة ومطحونة من 70% روبوستا فيتنامية و30% أرابيكا، معبأة في أكياس بصمام لتجارة التجزئة والفنادق والمطاعم والعلامات الخاصة.","description":"خلطة جاهزة للبيع: تمنح روبوستا المرتفعات الوسطى القوام والكريما، وتضيف أرابيكا لام دونغ الرائحة. نحمّصها وفق الدرجة المتفق عليها معكم، ونطحنها للإسبريسو أو الفلتر أو الفين، ونعبّئها في أكياس بصمام أحادي الاتجاه — وتحت علامتكم الخاصة عند الطلب.","origin":"روبوستا: المرتفعات الوسطى · أرابيكا: لام دونغ","specs":[{"label":"الخلطة","value":"70% روبوستا / 30% أرابيكا"},{"label":"الشكل","value":"محمّصة ومطحونة (حبوب كاملة عند الطلب)"},{"label":"درجة التحميص","value":"يُتفق عليها في كل طلبية"},{"label":"الطحن","value":"إسبريسو أو فلتر أو فين — حسب الطلب"}],"packaging":"أكياس بصمام أحادي الاتجاه لتصريف الغازات؛ علامة خاصة عند الطلب","moq":"عند الطلب"}}'::jsonb, true),
  ('cashew-ww160', 'Cashew Kernels WW160', 'cashew', 'White Wholes · 160', 'The largest AFI whole — for premium gifting and luxury retail in the Middle East and East Asia.', 'Cashew Kernels WW160 are whole white kernels graded to AFI at 140–160 kernels/lb (309–353/kg). The nuts are steamed, shelled, dried and peeled in Vietnam''s southeastern cashew belt, then sorted by size and colour and vacuum-packed to keep their crunch and sweetness on long ocean voyages.', 'https://images.unsplash.com/photo-1723466998060-533cd1af4e11', array['https://images.unsplash.com/photo-1615485925873-7ecbbe90a866', 'https://images.unsplash.com/photo-1754449503068-43215deac414']::text[], 'Southeast Vietnam (Binh Phuoc / Dong Nai)', '[{"label":"Count","value":"140–160 kernels/lb (309–353/kg)"},{"label":"Moisture","value":"5% max"},{"label":"Broken","value":"5% max"},{"label":"Colour","value":"White to pale ivory"},{"label":"Standard","value":"AFI specification"},{"label":"Crop","value":"2026"}]'::jsonb, '1 × 22.68 kg vacuum bag or 2 × 11.34 kg tins in 5-ply export cartons', '1 × 20ft container (700–720 cartons, about 16 MT)', false, 80, '{"ru":{"name":"Ядра кешью WW160","grade":"Белые цельные · 160","summary":"Самый крупный цельный калибр по AFI — для премиальных подарков и люкс-ритейла на Ближнем Востоке и в Восточной Азии.","description":"Ядра кешью WW160 — цельные белые ядра калибра 140–160 ядер/фунт (309–353/кг) по стандарту AFI. Орехи пропаривают, раскалывают, сушат и очищают на юго-востоке Вьетнама, затем сортируют по размеру и цвету и упаковывают под вакуумом, чтобы сохранить хруст и сладость в долгом морском рейсе.","origin":"Юго-восток Вьетнама (Биньфыок / Донгнай)","specs":[{"label":"Калибр","value":"140–160 ядер/фунт (309–353/кг)"},{"label":"Влажность","value":"не более 5%"},{"label":"Битые ядра","value":"не более 5%"},{"label":"Цвет","value":"Белый — светлая слоновая кость"},{"label":"Стандарт","value":"Спецификация AFI"},{"label":"Урожай","value":"2026"}],"packaging":"Вакуумный пакет 1 × 22,68 кг или жестяные банки 2 × 11,34 кг в пятислойных экспортных коробках","moq":"1 × 20ft контейнер (700–720 коробок, около 16 т)"},"ar":{"name":"كاجو WW160","grade":"كاجو أبيض كامل · 160","summary":"أكبر درجة كاملة وفق AFI — للهدايا الفاخرة والتجزئة الراقية في الشرق الأوسط وشرق آسيا.","description":"كاجو WW160 حبات كاجو بيضاء كاملة مصنّفة وفق AFI بعدد 140–160 حبة/رطل (309–353/كغ). تُبخَّر المكسرات وتُكسر قشرتها وتُجفَّف وتُنزع أغلفتها في حزام الكاجو جنوب شرق فيتنام، ثم تُفرز حسب الحجم واللون وتُعبّأ مفرّغة من الهواء للحفاظ على قرمشتها وحلاوتها خلال الرحلات البحرية الطويلة.","origin":"جنوب شرق فيتنام (بينه فوك / دونغ ناي)","specs":[{"label":"العدد","value":"140–160 حبة/رطل (309–353/كغ)"},{"label":"الرطوبة","value":"5% كحد أقصى"},{"label":"المكسور","value":"5% كحد أقصى"},{"label":"اللون","value":"أبيض إلى عاجي فاتح"},{"label":"المعيار","value":"مواصفات AFI"},{"label":"المحصول","value":"2026"}],"packaging":"كيس مفرّغ 1 × 22.68 كغ أو علبتا صفيح 2 × 11.34 كغ في كرتونة تصدير خماسية الطبقات","moq":"حاوية 20 قدم واحدة (700–720 كرتونة، نحو 16 طنًا)"}}'::jsonb, true),
